import React from 'react';

const QuanLyCuDan = () => {
    // Dữ liệu mẫu (Sau này sẽ lấy từ Database)
    const cuDanList = [
        { id: 1, ten: 'Phan Vinh', phong: 'A101', sdt: '0905123456', tinhTrang: 'Đã đóng phí' },
        { id: 2, ten: 'Nguyễn Văn A', phong: 'B202', sdt: '0905666777', tinhTrang: 'Nợ phí' },
    ];

    return (
        <div style={styles.container}>
            <div style={styles.header}>
                <h2>👤 Quản lý cư dân</h2>
                <button style={styles.addBtn}>+ Thêm cư dân mới</button>
            </div>
            <table style={styles.table}>
                <thead>
                    <tr style={styles.tr}>
                        <th style={styles.th}>ID</th>
                        <th style={styles.th}>Họ và Tên</th>
                        <th style={styles.th}>Phòng</th>
                        <th style={styles.th}>Số điện thoại</th>
                        <th style={styles.th}>Tình trạng</th>
                        <th style={styles.th}>Thao tác</th>
                    </tr>
                </thead>
                <tbody>
                    {cuDanList.map((item) => (
                        <tr key={item.id} style={styles.tr}>
                            <td style={styles.td}>{item.id}</td>
                            <td style={styles.td}><b>{item.ten}</b></td>
                            <td style={styles.td}>{item.phong}</td>
                            <td style={styles.td}>{item.sdt}</td>
                            <td style={styles.td}>
                                <span style={{...styles.status, backgroundColor: item.tinhTrang === 'Nợ phí' ? '#ff4d4d' : '#4caf50'}}>
                                    {item.tinhTrang}
                                </span>
                            </td>
                            <td style={styles.td}>
                                <button style={styles.editBtn}>Sửa</button>
                                <button style={styles.deleteBtn}>Xóa</button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};

const styles = {
    container: { backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 10px rgba(0,0,0,0.05)' },
    header: { display: 'flex', justifyContent: 'space-between', marginBottom: '20px' },
    addBtn: { padding: '10px 15px', backgroundColor: '#2e7d32', color: '#fff', border: 'none', borderRadius: '6px', cursor: 'pointer' },
    table: { width: '100%', borderCollapse: 'collapse', textAlign: 'left' },
    th: { padding: '12px', borderBottom: '2px solid #eee', color: '#666' },
    td: { padding: '12px', borderBottom: '1px solid #eee' },
    status: { padding: '4px 8px', color: '#fff', borderRadius: '4px', fontSize: '12px' },
    editBtn: { marginRight: '5px', backgroundColor: '#ffa000', color: '#fff', border: 'none', padding: '5px 10px', borderRadius: '4px', cursor: 'pointer' },
    deleteBtn: { backgroundColor: '#d32f2f', color: '#fff', border: 'none', padding: '5px 10px', borderRadius: '4px', cursor: 'pointer' }
};

export default QuanLyCuDan;
